package org.sleepwell.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import android.service.notification.*;import java.util.*;
/** API29+ explicit app rule. No global policy/interruption-filter setters are used. */
final class TrackingDndAndroid implements TrackingDndOwner.Port {
 final Context app;final NotificationManager notifications;TrackingDndAndroid(Context c){app=c.getApplicationContext();notifications=app.getSystemService(NotificationManager.class);}
 Uri condition(String token){return new Uri.Builder().scheme("condition").authority(app.getPackageName()).appendPath("tracking-dnd-v1").appendPath(token).build();}
 public boolean access(){return notifications!=null&&notifications.isNotificationPolicyAccessGranted();}public boolean exact(){return Build.VERSION.SDK_INT<31||app.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
 AutomaticZenRule rule(String id){return notifications.getAutomaticZenRule(id);}boolean matches(AutomaticZenRule rule,String token){return rule!=null&&condition(token).equals(rule.getConditionId())&&new ComponentName(app,TrackingDndActivity.class).equals(rule.getConfigurationActivity())&&rule.getOwner()==null;}
 static ZenPolicy policy(){return new ZenPolicy.Builder().allowAlarms(true).allowCalls(ZenPolicy.PEOPLE_TYPE_ANYONE).allowRepeatCallers(true).allowMedia(true).allowSystem(true).allowMessages(ZenPolicy.PEOPLE_TYPE_NONE).allowConversations(ZenPolicy.CONVERSATION_SENDERS_NONE).allowEvents(false).allowReminders(false).build();}
 public String create(String token){if(!access())throw new SecurityException("Allow Do Not Disturb access first.");AutomaticZenRule rule=new AutomaticZenRule("SleepWell · active tracking",null,new ComponentName(app,TrackingDndActivity.class),condition(token),policy(),NotificationManager.INTERRUPTION_FILTER_PRIORITY,false);String id=notifications.addAutomaticZenRule(rule);if(id==null||id.isEmpty())throw new IllegalStateException("Android could not create the tracking DND rule.");return id;}
 public boolean owned(String id,String token){return matches(rule(id),token);}public boolean enabled(String id,String token){AutomaticZenRule rule=rule(id);return matches(rule,token)&&rule.isEnabled();}
 Condition state(String token,int state){return new Condition(condition(token),"SleepWell tracking",state);}
 public void on(String id,String token){if(!owned(id,token))throw new IllegalStateException("DND rule ownership changed.");AutomaticZenRule rule=rule(id);rule.setEnabled(true);if(!notifications.updateAutomaticZenRule(id,rule))throw new IllegalStateException("Android could not enable the owned tracking rule.");notifications.setAutomaticZenRuleState(id,state(token,Condition.STATE_TRUE));}
 public void off(String id,String token){if(!owned(id,token))return;notifications.setAutomaticZenRuleState(id,state(token,Condition.STATE_FALSE));}
 public void remove(String id,String token){if(!owned(id,token))return;if(!notifications.removeAutomaticZenRule(id))throw new IllegalStateException("Android could not remove the owned tracking rule.");}
 Intent expiry(String token,long deadline){return new Intent(app,TrackingDndReceiver.class).setAction(TrackingDndReceiver.EXPIRE).setData(condition(token).buildUpon().appendQueryParameter("deadline",""+deadline).build()).putExtra("token",token).putExtra("deadline",deadline);}
 public void schedule(String token,long deadline){if(!exact())throw new SecurityException("Exact alarms are required for the DND expiry safeguard.");PendingIntent pending=PendingIntent.getBroadcast(app,551,expiry(token,deadline),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);app.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,deadline,pending);}
 public void cancel(String token,long deadline){PendingIntent pending=PendingIntent.getBroadcast(app,551,expiry(token,deadline),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_NO_CREATE);if(pending!=null){app.getSystemService(AlarmManager.class).cancel(pending);pending.cancel();}}
 public Map<String,String> ownedRules(){Map<String,String> result=new HashMap<>();for(Map.Entry<String,AutomaticZenRule> item:notifications.getAutomaticZenRules().entrySet()){Uri uri=item.getValue().getConditionId();if(uri==null||!"condition".equals(uri.getScheme())||!app.getPackageName().equals(uri.getAuthority())||uri.getPathSegments().size()!=2||!uri.getPathSegments().get(0).equals("tracking-dnd-v1"))continue;String token=uri.getLastPathSegment();if(matches(item.getValue(),token))result.put(item.getKey(),token);}return result;}
}
